// models/homograph_model.js
// Homograph / IDN lookalike-domain classifier.
//
// The compiled model is generated by homograph_module/export_js.py (logistic
// regression over the six homograph features) and copied in by
// homograph_module/sync_to_extension.sh. This file is only the adapter that
// turns Visor's feature vector into that model's input.
//
// The vector this receives has already been projected onto the homograph
// allowlist by models/interface.js, so this model can only see the six
// features it is allowed to read.

import { HomographData } from './homograph_data.js';
import { HomographFeatures } from './homograph_features.js';
import { HomographModel } from './homograph_classifier.js';

const MODEL = HomographModel;

function num(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  return 0;
}

/**
 * classify(fv) -> { verdict, score, module }
 *
 * fv carries the six homograph features, extracted from the page's hostname by
 * feature_extractor/homograph.js.
 */
export function classify(fv) {
  if (!fv || typeof fv !== 'object') {
    return { verdict: 'safe', score: 0.0, module: 'homograph' };
  }

  const input = MODEL.FEATURE_ORDER.map((k) => num(fv[k]));
  const p = MODEL.score(input)[1];
  const score = Number.isFinite(p) ? p : 0;

  return {
    verdict: score >= MODEL.THRESHOLD ? 'suspicious' : 'safe',
    score: Math.round(score * 1000) / 1000,
    module: 'homograph',
  };
}

/** The brand this host impersonates, when the reference list matched one. */
export function impersonatedTarget(fv) {
  return (fv && typeof fv.homograph_impersonates === 'string') ? fv.homograph_impersonates : null;
}

export const HOMOGRAPH_THRESHOLD = MODEL.THRESHOLD;
export const HOMOGRAPH_FEATURES = MODEL.FEATURE_ORDER;
